insert into public.daily_puzzles (puzzle_number, puzzle_date, word_id)
select s.puzzle_number, s.puzzle_date, w.id
from scheduled s
join public.words w on w.normalized_word = s.normalized_word
on conflict (puzzle_date) do update
  set puzzle_number = excluded.puzzle_number,
      word_id       = excluded.word_id;
